#iframe-container {
  width: 100%;
  max-width: 700px;
  height: 600px;
  border: none;
  display: block;
  overflow: hidden;
  line-height: 0;
  margin: 0;
}

/* Specific range */
@media (min-width: 260px) and (max-width: 400px) {
  #iframe-container {
    height: 580px;
  }
}

@media (min-width: 400px) and (max-width: 540px) {
  #iframe-container {
    height: 560px;  /* 510 → 530 */
  }
}

/* 580px–700px range */
@media (min-width: 541px) and (max-width: 700px) {
  #iframe-container {
    height: 500px;
  }
}

/* Medium screens */
@media (min-width: 701px) and (max-width: 1100px) {
  #iframe-container {
    height: 508px;
  }
}

/* Large screens */
@media (min-width: 1101px) {
  #iframe-container {
    height: 513px;
  }
}

/* Extra large screens */
@media (min-width: 1440px) {
  #iframe-container {
    height: 518px;
  }
}
